{
  "returncode": 0,
  "output_head": ".admin-dashboard-index {
  > header h2 {
    border-bottom: 1px solid $border;
    text-transform: uppercase;
  }

  address {
    > :not(:last-child) {
      &::after {
        content: "";
        display: block;
        margin-bottom: calc($line-height / 3);
      }
    }

    a {
      &[href^="mailto:"] {
        @include has-fa-icon(envelope, regular);
      }

      &[href^="http"] {
        @include has-fa-icon(globe, solid);
      }

      &::before {
        margin-#{$global-right}: 0.2em;
        transform: translateY(-0.2em);
      }
    }
  }
}
.proposal-featured {
  min-height: $line-height * 3.5;

  .info {
    > :last-child {
      &::before {
        @include circle-separator;
      }
    }
  }

  .supports {
    @include supports;
    background: none;
    border: 0;
    padding-bottom: 0;
    padding-top: 0;

    &::after {
      content: none;
    }

    .progress,
    .total-supports {
      display: none;
    }

    .button-support {
      background: $body-font-color;
      color: $featured;
      margin-top: 0;

      &:hover {
        @extend %body-colors;
      }
    }

    .participation-not-allowed {
      background: $featured;
      padding-top: 0;

      a {
        color: inherit;
      }

      p {
        color: $color-warning;
        font-size: $small-font-size;
        line-height: $line-height;
      }
    }

    .supported {
      background: none;
      border: 0;
      font-size: $small-font-size;
      margin-bottom: 0;
      margin-top: 0;
      padding: 0;
    }
  }

  .share-supported {

    .social-share-button .ssb-icon {
      background: none;
      color: inherit;
